Then, we define several norms for signal. 
\begin{itemize}
\item For any continuous interval $U\subset \R$, the continuous $U$-norm of $x$ is defined as
\begin{align*}
    \|x(t)\|_U^2 = \frac{1}{|U|}\int_U |x(t)|^2\d t.
\end{align*}
\item For any $T>0$, the \emph{continuous $T$-norm} is defined as 
\begin{align*}
    \|x(t)\|^2_T=\frac{1}{T} \int_0^T |x(t)|^2\d t.
\end{align*}
\item Let $D$ be a probability distribution over $\mathbb{R}$. The \emph{continuous $D$-norm} is defined as
\begin{align*}
