\begin{theorem}[\cite{k08}] \label{thm:energy_bound}
For  any $t \in [0,T]$,
\begin{align*}
    \underset{x \in {\cal F}_{k,F}}{\sup} \frac{|x(t)|^2}{\|x\|_T^2} \lesssim k^2.
\end{align*}
\end{theorem}

\begin{theorem}[\cite{cp19_colt, be06}] \label{thm:bound_k_sparse_FT_x_middle}
