\end{align*}
\end{theorem}

\begin{definition}[$G$-filter's construction, \cite{ckps16}]\label{def:define_G_filter}
Given $B >1$, $\delta >0$, $\alpha>0$. Let $l := \Theta( \log(k/\delta) )$.
Define $G_{B,\delta,\alpha}(t)$ and its Fourier transform $\wh{G_{B,\delta,\alpha}}(f)$ as follows:
\begin{eqnarray*}
G_{B,\delta,\alpha}(t):= &~ b_0 \cdot (\rect_{ \frac{B}{(\alpha \pi)}} (t) )^{\star  l} \cdot  \sinc(t \frac{\pi}{2B}), \\
\widehat{G_{B,\delta,\alpha}}(f):= &~ b_0 \cdot ( \sinc(\frac{B}{\alpha \pi} f) )^{ l} * \rect_{\frac{\pi}{2B}}(f),
\end{eqnarray*}
where $b_0 = \Theta(B \sqrt{l}/\alpha)$ is the normalization factor such that $\wh{G}(0)=1$. \end{definition}

\begin{definition}[Filter for bins]\label{def:G_j_sigma_b}
