\begin{proof}
Let $I=I_{\sigma,b}^{(j)}$ be the corresponding ideal filter as in Eq.~\eqref{eq:def_ideal_filter}. 
Let $S:=\supp(\wh{x}*\wh{H})$ be the support set of $\wh{x}*\wh{H}$. 
We have $|S|\leq \Delta$. 

Let $z_I(t)$, $d_{z,I}(t)$ be defined as in Lemma~\ref{lem:z_diff_xHG_sub_XHI_is_small} and $x_I(t)$, $d_{I,x}(t)$ be defined as in Lemma~\ref{lem:z_diff_xIH2xHI}.

Before proving the energy bound for $|d_z(t)|$, we first consider the signal $x_I(t)\cdot  e^{2\pi\i f_0 \beta} - x_I(t+\beta)$. 
By Fourier transformation, we know that its Fourier coefficient of a frequency $f$ is:
\begin{align*}
    \wh{x}_I(f)  e^{2\pi\i f_0 \beta} - \wh{x}_I(f) e^{2\pi\i f \beta} = \wh{x}(f)\cdot \wh{I}(f)  e^{2\pi\i f_0 \beta} - \wh{x}(f)\cdot \wh{I}(f) e^{2\pi\i f \beta}
\end{align*}
Thus, $x_I(t)\cdot  e^{2\pi\i f_0 \beta} - x_I(t+\beta)$ is at most $k$-Fourier-sparse. 

Let $[L,R]:=U$. By Fourier-sparse signals' energy bound (Theorem \ref{thm:bound_k_sparse_FT_x_middle} and Theorem \ref{thm:energy_bound}), we have
\begin{align}
  |  x_I(t)\cdot  e^{2\pi\i f_0 \beta} - x_I(t+\beta) |^2 \lesssim &~ {\min} \Big\{\frac{k }{\min\{R-t, t-L\}}, k^2\Big\} \cdot  \|  x_I(t)\cdot  e^{2\pi\i f_0 \beta} - x_I(t+\beta) \|_{D_U}^2\notag \\
  \lesssim &~ {\min} \{\frac{k }{1-|2t/T-1|}, k^2\} \cdot  \|  x_I(t)\cdot  e^{2\pi\i f_0 \beta} - x_I(t+\beta) \|_{D_U}^2 
  \label{eq:1_d_x_I_z_diff_condition_number_xI}
\end{align}
where the first step follows from applying Theorem \ref{thm:bound_k_sparse_FT_x_middle} with $x(t)=x(Tt/2+T/2) $ and applying Theorem \ref{thm:energy_bound} with $T=|U|, x(t)=x(t+L) $, the second step follows from $ [-1+0.5/k, 1-0.5/k] \subseteq [L,R]$, which implies that $k(\min\{R-t, t-L\})^{-1} \lesssim k(1-|2t/T-1|)^{-1} $ for any $|t|\in [L+1/k, R-1/k]$. Moreover, for any $|t|\in [L, L+1/k]\cup [R-1/k, R]$, $k^2 \lesssim k(1-|2t/T-1|)^{-1} $. 

