    = &~  \| d_{I, z}(t)\|_{D_U}^2 +   \delta_1^2 \|x_I(t)\|^2_{T}\notag \\
    \lesssim &~   \|d_z(t)\|_{D_U}^2 + \| d_{I, z}(t)-d_z(t)\|_{D_U}^2 +   \delta_1^2 \|x_I(t)\|^2_{T}\notag \\
