where the first step follows from $(a+b)^2\leq 2a^2+2b^2$, the second step follows from Lemma \ref{lem:z_diff_norm_condition_number_xI_pre}, the third step follows from Lemma \ref{lem:z_diff_xIH2xHI}, the forth step follows from $(a+b)^2\leq 2a^2+2b^2$, the last step follows from Claim \ref{clm:x_I2x}.
For the second term, we have that
\begin{align*}
    &~ \| d_{I, z}(t)-d_z(t)\|_{D_U}^2 \notag \\
   \lesssim &~    \frac{1}{|U|} \int_{U} | d_{I, z}(t)-d_z(t)|^2 \d t \notag \\
\lesssim &~    \frac{1}{|U|} \int_{-\infty}^\infty | d_{I, z}(t)-d_z(t)|^2 \d t \notag \\
 \lesssim &~    \frac{1}{|U|} \delta_1^2 \|x(t)\|^2_{T} \notag \\
  \lesssim &~     \delta_1^2 \|x(t)\|^2_{T} 
\end{align*}
where the first step follows from the definition of the norm, second step  is straight forward, the third step follows from Lemma \ref{lem:z_diff_xHI_sub_XHG_T_norm_is_small} with appropriate scaling, the forth step follows from $|U|\gtrsim 1$. Hence,
\begin{align}\label{eq:1p5_d_I_z_diff_condition_number_xI}
    \|  x_I(t)\cdot  e^{2\pi\i f_0 \beta} - x_I(t+\beta) \|_{D_U}^2 \lesssim \|d_z(t)\|_{D_U}^2 + \delta_1^2\|x(t)\|_{T}^2.
\end{align}

Therefore, we have that
\begin{align}
   |d_{I, z}(t)|^2 =&~ |d_{I, x}(t)|^2 \notag \\
    \lesssim &~ (|x_I(t)\cdot  e^{2\pi\i f_0 \beta} - x_I(t+\beta)|+ \delta_1 k \|x_I(t)\|_{T})^2 \notag \\
    \lesssim &~ |x_I(t)\cdot  e^{2\pi\i f_0 \beta} - x_I(t+\beta)|^2+ \delta_1^2 k^2 \|x_I(t)\|_{T}^2 \notag \\
    \lesssim &~ |x_I(t)\cdot  e^{2\pi\i f_0 \beta} - x_I(t+\beta)|^2+ \delta_1 \|x_I(t)\|_{T}^2 \notag \\
    \lesssim &~ {\min} \{\frac{k }{1-|2t/T-1|}, k^2\} \cdot  \|  x_I(t)\cdot  e^{2\pi\i f_0 \beta} - x_I(t+\beta) \|_{D_U}^2 + \delta_1 \|x_I(t)\|_{T}^2\notag \\
   \lesssim &~ {\min} \{\frac{k }{1-|2t/T-1|}, k^2\} \cdot  \|  x_I(t)\cdot  e^{2\pi\i f_0 \beta} - x_I(t+\beta) \|_{D_U}^2 + \delta_1 \|x(t)\|_{T}^2 \notag \\
\lesssim &~ {\min} \{\frac{k }{1-|2t/T-1|}, k^2\} \cdot  (\|d_z(t)\|_{D_U}^2  +   \delta_1^2 \|x(t)\|^2_{T}) + \delta_1 \|x(t)\|_{T}^2 \notag \\
\lesssim &~ {\min} \{\frac{k }{1-|2t/T-1|}, k^2\} \cdot  \|d_z(t)\|_{D_U}^2  + \delta_1 \|x(t)\|_{T}^2, 
\label{eq:2_d_I_z_diff_condition_number_xI}
\end{align}
where the first step follows from Lemma \ref{lem:z_diff_xIH2xHI}, the second step follows from Lemma \ref{lem:z_diff_condition_number_xI_pre}, the third step follows from $(a+b)^2\leq 2a^2+2b^2$, the forth step follows from $\delta_1 k^2 \leq 1$, the fifth step follows from Eq.~\eqref{eq:1_d_x_I_z_diff_condition_number_xI}, the six step follows from Claim \ref{clm:x_I2x}, the seventh step follows from Eq.~\eqref{eq:1p5_d_I_z_diff_condition_number_xI}, the last step follows from $\delta_1 k^2 \lesssim 1 $.

Finally, we have
\begin{align*}
    |d_z(t)|^2 \leq &~ 2|d_z(t)-d_{I,z}(t)|^2 + 2|d_{I, z}(t)|^2 \notag \\
    \leq &~ 2\delta_1^2 T|S| \cdot  \|x(t) \|_{T}^2 + 2|d_{I, z}(t)|^2 \notag \\
    \leq &~ 2\delta_1 \cdot  \|x(t) \|_{T}^2 + 2|d_{I, z}(t)|^2 \notag \\
    \lesssim &~ \delta_1 \cdot  \|x(t) \|_{T}^2 +  {\min} \{\frac{k }{1-|2t/T-1|}, k^2\} \cdot  \|d_z(t)\|_{D_U}^2   
\end{align*}
where the first step follows from $ (a+b)^2\leq 2a^2+2b^2$, the second step follows from Lemma \ref{lem:z_diff_xHG_sub_XHI_is_small}, the third step follows from $\delta_1 T|S| \leq 1$, the forth step follows from Eq.~\eqref{eq:2_d_I_z_diff_condition_number_xI}. 

The lemma is then proved.

\end{proof}
